    [Fact]
    public void ReferenceScenario_Etapa3Nodes_PresentWithCorrectPositionAndEntrouPor()
    {
        var path = ReferenceScenario.Path!;
        var pathById = path.ToDictionary(n => n.Id, StringComparer.Ordinal);

        // Posições esperadas (0-based = passo - 1) conforme o card
        var expected = new (int PassoZeroBased, string NodeId, string? ExpectedEntrouPor)[]
        {
            (14, "_LeuhgFqVEfG5K7mY0I3I6w", "fluxo"),   // passo 15 — linkThrow
            (15, "_CI6l0VqREfG5K7mY0I3I6w", "link"),    // passo 16 — linkCatch (entrada explícita)
            (16, "_CI6lx1qREfG5K7mY0I3I6w", "fluxo"),   // passo 17
