    // =========================================================================
    // AC3 — rasto bate passo a passo com o percurso do cenário (fixture)
    //        Para cada cenário POC_EpatProcess da etapa 3:
    //          a) Cada nó nos segmentos de etapa 3 tem ID não vazio.
    //          b) Segmentos de etapa 3 estão ordenados por ordemNaJornada.
    //          c) Dentro de cada segmento, os nós aparecem na sequência declarada.
    //          d) Cada segmento tem pelo menos um nó.
    // =========================================================================

    [Theory]
    [MemberData(nameof(Etapa3PocEpatScenarioIds))]
    public void Etapa3_POCEpatProcess_Scenario_Etapa3Nodes_MatchReferenceOrderStepByStep(
        string scenarioId)
    {
        var detail = ScenarioFixtureLoader.LoadScenario(scenarioId);

        // Filtrar apenas segmentos que pertencem à etapa 3
        var etapa3Segments = (detail.Segmentos ?? [])
            .Where(s => s.Etapas != null && s.Etapas.Contains(3))
            .OrderBy(s => s.OrdemNaJornada)
            .ToList();

        Assert.True(etapa3Segments.Count > 0,
            $"[{scenarioId}] Nenhum segmento com etapas=[..3..] encontrado.");

        // (b) Segmentos ordenados por ordemNaJornada
        int prevOrdem = -1;
        foreach (var seg in etapa3Segments)
        {
            Assert.True(seg.OrdemNaJornada >= prevOrdem,
                $"[{scenarioId}] Segmento etapa 3 fora de ordem: " +
                $"ordemNaJornada={seg.OrdemNaJornada} < anterior={prevOrdem}.");
            prevOrdem = seg.OrdemNaJornada;

            // (d) Cada segmento tem pelo menos um nó
            Assert.True(seg.Nos is { Count: > 0 },
                $"[{scenarioId}] Segmento etapa 3 ordemNaJornada={seg.OrdemNaJornada} " +
                $"(doPasso={seg.DoPasso}) está vazio — rasto ausente.");

            // (a) Cada nó tem ID não vazio
            foreach (var no in seg.Nos!)
            {
                Assert.False(string.IsNullOrWhiteSpace(no.Id),
                    $"[{scenarioId}] Nó com id vazio no segmento doPasso={seg.DoPasso}.");
            }

            // (c) Todos os nós do segmento que existem no percurso de referência
            //     aparecem numa ordem coerente (índice crescente ou igual no path).
            //     Nós de sub-processo podem não estar no path principal — são aceites.
            int prevRefIdx = -1;
            foreach (var no in seg.Nos!)
            {
                if (!ReferenceNodeOrder.TryGetValue(no.Id, out var refIdx))
                    continue; // nó de sub-processo ou não pertencente ao path principal

                Assert.True(refIdx >= prevRefIdx,
                    $"[{scenarioId}] Nó '{no.Id}' (refIdx={refIdx}) fora de ordem " +
                    $"no segmento doPasso={seg.DoPasso} — desvio no passo {refIdx + 1}.");
                prevRefIdx = refIdx;
            }
        }

        var totalNodes = etapa3Segments.SelectMany(s => s.Nos!).Count();
        _output.WriteLine(
            $"[ok] {scenarioId}: {etapa3Segments.Count} segmento(s) de etapa 3, " +
            $"{totalNodes} nós — todos estruturalmente válidos.");
    }

