    [Fact]
    public void Etapa3_POCEpatProcess_Coverage_AllEtapa3ReferenceNodesVisitedAcrossScenarios()
    {
        var pocScenarios = Etapa3Scenarios
            .Where(s => s.Process == "POC_EpatProcess")
            .ToList();

        var coveredIds = new HashSet<string>(StringComparer.Ordinal);

        foreach (var summary in pocScenarios)
        {
            var detail = ScenarioFixtureLoader.LoadScenario(summary.Id);
            var etapa3Nodes = (detail.Segmentos ?? [])
                .Where(s => s.Etapas != null && s.Etapas.Contains(3))
                .SelectMany(s => s.Nos ?? [])
                .Select(n => n.Id)
                .Where(id => !string.IsNullOrWhiteSpace(id));

            foreach (var id in etapa3Nodes)
                coveredIds.Add(id!);
        }

        var missing = Etapa3ReferenceNodeIds
            .Where(id => !coveredIds.Contains(id))
            .ToList();

        Assert.Empty(missing);

        _output.WriteLine(
            $"[ok] Todos os {Etapa3ReferenceNodeIds.Count} nós de referência da etapa 3 " +
            $"são cobertos pelos {pocScenarios.Count} cenários POC_EpatProcess.");
    }

