    public void Etapa3_Scenario_FixtureIsReadOnly_PathFieldNotWrittenByHarness(string scenarioId)
    {
        var detail = ScenarioFixtureLoader.LoadScenario(scenarioId);

        // O arnes apenas lê — nunca escreve. A presença do campo 'path' ou 'segmentos'
