        Assert.True(hasSomeTrace,
            $"[{scenarioId}] Fixture sem rasto (path[] e segmentos[] vazios) — " +
            "o oráculo não pode ser provado sem rasto na fixture.");

        _output.WriteLine($"[ok] {scenarioId}: fixture contém rasto de instância (imutável).");
    }

    // =========================================================================
    // AC-ORACULO — rasto passo a passo: para cada cenário, a sequência de nós
    //              do segmento etapa 3 coincide na totalidade com o percurso
    //              de referência, sem omitir nenhum nó canónico
    // =========================================================================

    /// <summary>
    /// AC-ORACULO — Para cada cenário POC_EpatProcess de etapa 3, verifica que
    /// todos os nós canónicos do segmento etapa 3 (passos 15–21) que devem
    /// aparecer nesse cenário estão presentes e na ordem correcta.
    ///
    /// "Qualquer desvio deve produzir uma falha de teste identificada pelo id
    /// do nó divergente." (AC2 do card)
    /// </summary>
    [Theory]
    [MemberData(nameof(Etapa3PocEpatScenarioIds))]
    public void Etapa3_Oracle_ScenarioPath_MatchesReferenceStepByStep(string scenarioId)
    {
        var detail = ScenarioFixtureLoader.LoadScenario(scenarioId);

        var etapa3SegmentNodes = (detail.Segmentos ?? [])
            .Where(s => s.Etapas != null && s.Etapas.Contains(3))
            .OrderBy(s => s.OrdemNaJornada)
            .SelectMany(s => s.Nos ?? [])
            .ToList();

        Assert.True(etapa3SegmentNodes.Count > 0,
            $"[{scenarioId}] AC-ORACULO: nenhum nó de etapa 3 encontrado no rasto.");

        // Colectar os nós canónicos de etapa 3 que este cenário deve conter.
        // O percurso de referência é linear (passos 15–21); cenários podem
        // não cobrir todos os 7 nós se terminarem antes, mas os que cobrem
        // devem estar na ordem correcta.
        var traceIds = etapa3SegmentNodes
            .Select(n => n.Id)
            .Where(id => !string.IsNullOrWhiteSpace(id))
            .ToList();

        var etapa3RefIds = Etapa3ReferenceNodeIds.ToHashSet(StringComparer.Ordinal);

        // Apenas os nós canónicos de etapa 3 (que existem no percurso de referência)
        var canonicalInTrace = traceIds
            .Where(id => etapa3RefIds.Contains(id!))
            .Select(id => id!)
            .ToList();

        // Verificar que os nós canónicos aparecem em ordem crescente de índice
        // de referência (sem retrocesso).
        int prevRefIdx = -1;
        foreach (var nodeId in canonicalInTrace)
        {
            var refIdx = ReferenceNodeOrder[nodeId]; // já existe — garantido por etapa3RefIds
            Assert.True(refIdx > prevRefIdx,
                $"[{scenarioId}] AC-ORACULO: nó divergente '{nodeId}' " +
                $"(refIdx={refIdx}) aparece fora de ordem após refIdx={prevRefIdx}. " +
                $"Passo de divergência: {refIdx + 1}.");
            prevRefIdx = refIdx;
        }

        _output.WriteLine(
            $"[ok-oraculo] {scenarioId}: {canonicalInTrace.Count} nó(s) canónico(s) de etapa 3 " +
            $"em ordem correcta ({string.Join(" → ", canonicalInTrace.Select(id => $"passo {ReferenceNodeOrder[id] + 1}"))}).");
    }
